import sys
import math

def inpf():
    a = sys.stdin.readline().strip().split(" ")
    return list(map(float, a))

def inps():
    a = sys.stdin.readline().strip().split(" ")
    return a

def copy(a):
    import copy as _copy
    return _copy.deepcopy(a)

def kaijo(n, r=10**9+7):
    if n < 2:
        return 1
    memo = 1
    for u in range(2, n + 1):
        memo = (memo * u) % r
    return memo

def na(n, d=0):
    return [d] * n

def na2(n, m, d=0):
    return [[d] * m for _ in range(n)]

def na3(n, m, l, d=0):
    return [[[d] * l for _ in range(m)] for _ in range(n)]

def inp():
    a = sys.stdin.readline().strip().split(" ")
    return list(map(int, a))

def r_up(a, b):
    return (a + b - 1) // b

def sum_(a):
    return sum(a)

def prime_division(n):
    res = []
    tmp = n
    i = 2
    while i * i <= tmp:
        if tmp % i == 0:
            cnt = 0
            while tmp % i == 0:
                cnt += 1
                tmp //= i
            res.append((i, cnt))
        i += 1 if i == 2 else 2
    if tmp > 1:
        res.append((tmp, 1))
    return res

n = inp()[0]

d = prime_division(n)
if len(d) == 1:
    print(d[0][0])
else:
    print(1)

